import Foundation

struct LocaleDirectionChecker {
    func isRightToLeft(localeIdentifier: String) -> Bool {
        let rtlLanguages = ["ar", "he", "fa", "ur"]
        let prefix = String(localeIdentifier.prefix(2))
        return rtlLanguages.contains(prefix)
    }
}

let checker = LocaleDirectionChecker()
let isRTL = checker.isRightToLeft(localeIdentifier: "ar_SA")
print("Direction: \(isRTL ? "RightToLeft" : "LeftToRight")")

import Foundation

struct GreetingTemplate {
    let template: String

    func resolve(userName: String) -> String {
        template.replacingOccurrences(of: "{name}", with: userName)
    }
}

let greeting = GreetingTemplate(template: "Welcome, {name}!")
print("Message: \(greeting.resolve(userName: "Taylor"))")

